{
  "justification": "Vote-deciding salience clusters around health, education, and care for the elderly, and the electorate leans mildly left with a strong preference (71.3%) to raise taxes to expand services—signals of heightened Care and Equality concerns. Low salience for crime/authority, defense/foreign affairs, and family values—and only a minority favoring lower taxes—points to weaker Authority, Loyalty, and Sanctity, with Proportionality present but secondary.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "Health (33.6%), education (25.6%), pensions/elderly (4.3%) top salience; 71.3% back higher tax-and-services.",
      "weight": 0.42
    },
    {
      "foundation": "equality",
      "basis": "71.3% favor expanding social services via higher taxes; left-right mean 2.39/5; equality/social justice salience 0.8%.",
      "weight": 0.22
    },
    {
      "foundation": "proportionality",
      "basis": "28.7% prefer lower tax/services; salience for macro-economy (7.9%), tax (3.2%), inflation/wages (1.2%).",
      "weight": 0.13
    },
    {
      "foundation": "authority",
      "basis": "Law and order/crime/policing/sentencing/prisons salience 3.6% with overall left tilt (2.39/5).",
      "weight": 0.1
    },
    {
      "foundation": "loyalty",
      "basis": "Defense 0.2%, foreign affairs 0.1%, EU not measured—national/group-solidarity cues minimal.",
      "weight": 0.07
    },
    {
      "foundation": "sanctity",
      "basis": "Family values 0.2% and environment 1.0% indicate weak purity/naturalness concerns.",
      "weight": 0.06
    }
  ]
}
